function n(t){const e=document.getElementById("donutChart");new Chart(e,{type:"doughnut",data:t,options:{cutout:53,plugins:{legend:{labels:{boxWidth:10,boxHeight:10,color:"#000",padding:12},position:"right",borderRadius:20}}}})}function o(t){const e=document.getElementById("barChart");new Chart(e,{type:"bar",data:t,options:{aspectRatio:1,plugins:{legend:{labels:{boxWidth:10,boxHeight:10,color:"#000",padding:12},position:"right",borderRadius:20}}}})}function i(t){const e=document.getElementById("lineChart").getContext("2d");window.myLineChart=new Chart(e,{type:"line",data:t,options:{responsive:!0,maintainAspectRatio:!1,plugins:{legend:{display:!1}},scales:{x:{grid:{display:!1}},y:{grid:{display:!1}}}}})}export{o as b,n as d,i as l};
